}

function findFlowDefinition(rt, module) {
  const candidates = [
    module.default,
    module["module.exports"],
    nestedDefault(module.default),
    nestedDefault(module["module.exports"]),
  ];
  return candidates.find((candidate) => rt.__isDefinedFlow(candidate)) ?? null;
}

function nestedDefault(value) {
  if (!value || typeof value !== "object" || !("default" in value)) {
    return null;
  }
  return value.default ?? null;
}

// What the runner needs of the flow: acpx's definition snapshot as its `flow.json` has it,
// and each node's settings as the flow gives them.
function describeFlow(definition) {
  const title = definition.run?.title;
  return {
    name: definition.name,
    startAt: definition.startAt,
    edges: definition.edges,
    permissions: definition.permissions ?? null,
    title: typeof title === "string" ? { value: title } : title === undefined ? null : { function: true },
    snapshot: createFlowDefinitionSnapshot(definition),
    nodes: Object.entries(definition.nodes).map(([id, node]) => describeNode(id, node)),
  };
}

function describeNode(id, node) {
  const has = (key) => Object.prototype.hasOwnProperty.call(node, key);
  return {
    id,
    nodeType: node.nodeType,
    ...(node.timeoutMs !== undefined ? { timeoutMs: node.timeoutMs } : {}),
    ...(node.heartbeatMs !== undefined ? { heartbeatMs: node.heartbeatMs } : {}),
    ...(node.statusDetail !== undefined ? { statusDetail: node.statusDetail } : {}),
    ...(node.summary !== undefined ? { summary: node.summary } : {}),
    ...(node.profile !== undefined ? { profile: node.profile } : {}),
    ...(node.session !== undefined
      ? {
          session: {
            ...(node.session.handle !== undefined ? { handle: node.session.handle } : {}),
            isolated: Boolean(node.session.isolated),
          },
        }
      : {}),
    ...(typeof node.cwd === "string" ? { cwd: node.cwd } : {}),
    callbacks: ["run", "prompt", "parse", "exec", "cwd"].filter((key) => typeof node[key] === "function"),
    hasRun: has("run"),
    hasExec: has("exec"),
  };
}

// acpx's `createFlowDefinitionSnapshot` (`src/flows/store.ts`).
function createFlowDefinitionSnapshot(definition) {
  return {
    schema: "acpx.flow-definition-snapshot.v1",
    name: definition.name,
    ...(definition.run?.title !== undefined ? { run: { hasTitle: true } } : {}),
    ...(definition.permissions ? { permissions: structuredClone(definition.permissions) } : {}),
    startAt: definition.startAt,
    nodes: Object.fromEntries(Object.entries(definition.nodes).map(([nodeId, node]) => [nodeId, snapshotNode(node)])),
    edges: structuredClone(definition.edges),
  };
}

function snapshotNode(node) {
  const common = {
    nodeType: node.nodeType,
    ...(node.timeoutMs !== undefined ? { timeoutMs: node.timeoutMs } : {}),
    ...(node.heartbeatMs !== undefined ? { heartbeatMs: node.heartbeatMs } : {}),
    ...(node.statusDetail ? { statusDetail: node.statusDetail } : {}),
  };
  switch (node.nodeType) {
    case "acp":
      return {
        ...common,
        ...(node.profile ? { profile: node.profile } : {}),
        session: {
          ...(node.session?.handle ? { handle: node.session.handle } : {}),
          ...(node.session?.isolated ? { isolated: true } : {}),
        },
        cwd: typeof node.cwd === "function" ? { mode: "dynamic" } : typeof node.cwd === "string" ? { mode: "static", value: node.cwd } : { mode: "default" },
        hasPrompt: true,
        hasParse: typeof node.parse === "function",
      };
    case "compute":
      return { ...common, hasRun: true };
    case "action":
      return {
        ...common,
        actionExecution: "exec" in node ? "shell" : "function",
        hasRun: "run" in node,
        hasExec: "exec" in node,
        hasParse: "parse" in node && typeof node.parse === "function",
      };
    case "checkpoint":
      return { ...common, ...(node.summary ? { summary: node.summary } : {}), hasRun: typeof node.run === "function" };
  }
  throw new Error(`Unsupported flow node type: ${String(node.nodeType)}`);
}

// acpx's `resolveFlowRunTitle`, the part a title function needs.
async function flowTitle(params) {
  const value = await flow.run.title({ input, flowName: flow.name, flowPath: params.flowPath });
  return returnedValue(value);
}

// One node callback, called as acpx's runner calls it, with the step context it builds
// (`makeFlowNodeContext`): the live input and outputs, and a copy of the run state.
async function invoke(params) {
  const { nodeId, fn, attemptId } = params;
  const node = flow.nodes[nodeId];
  const attempt = attemptFor(attemptId);
  running.set(attemptId, attempt);
  const state = params.state;
  state.input = input;
  state.outputs = outputs;
  const ctx = {
    input,
    outputs,
    results: state.results,
    state,
    services: {},
    signal: attempt.controller.signal,
  };
  if (node.nodeType === "action" && "run" in node) {
    ctx.runShell = (execution) => runShell(attemptId, attempt, execution);
  }
  try {
    // A shell action's `parse` gets the command's result with the `args` of the spec its
    // `exec` gave, as acpx's does.
    const shellParse = fn === "parse" && node.nodeType === "action";
    const arg = shellParse ? commandResult(params.arg, returned.get(attemptId)) : params.arg;
    const args = "arg" in params ? [arg, ctx] : [ctx];
    const value = await node[fn](...args);
    if (!attempt.finished) returned.set(attemptId, value);
    if (node.nodeType === "acp" && fn === "cwd") {
      // acpx's `resolveNodeCwd`: against the agent's working directory, which stands in
      // for none; `path.resolve` refuses what is not a string.
      return { value: path.resolve(params.defaultCwd, value ?? params.defaultCwd) };
    }
    if (node.nodeType === "acp" && fn === "prompt") return acpPrompt(attempt, value);
    return returnedValue(fn === "exec" ? encodeExecution(value, ["cwd", "timeoutMs"]) : value);
  } catch (error) {
    attempt.thrown = { error };
    throw error;
  } finally {
    if (running.get(attemptId) === attempt) running.delete(attemptId);
  }
}

// acpx's `prepareAcpPrompt`, the part that needs the flow's own value: the prompt — a
// string made a text block (`normalizePromptInput`) — and the text its bundle shows of it
// (`promptToDisplayText`), or what making that text threw. The runner throws that once it
// has checked the attempt, as acpx's runner does; the attempt is then cancelled with it.
function acpPrompt(attempt, value) {
  const prompt = typeof value === "string" ? runtime.__textPrompt(value) : value;
  try {
    return { ...returnedValue(prompt), promptText: runtime.__promptToDisplayText(prompt) };
  } catch (error) {
    attempt.thrown = { error };
    const isError = error instanceof Error;
    return { ...returnedValue(prompt), promptTextError: { message: isError ? error.message : String(error), isError } };
  }
}

// acpx's `runCallbackShell`, which is `attempt.own(...)` around the command: an attempt no
// longer taking work refuses at once — with the reason it was cancelled for, or as
// finished — as does an execution whose `cwd` `path.resolve` refuses. The runner runs the
// command.
function runShell(attemptId, attempt, execution) {
  attempt.controller.signal.throwIfAborted();
  if (attempt.finished) throw new Error("Flow attempt has finished accepting work");
  path.resolve(".", execution.cwd ?? ".");
  return request("shell/run", { attemptId, execution: encodeExecution(execution, ["cwd"]) }).then((result) =>
    commandResult(result, execution),
  );
}

// A value JSON cannot carry in a shell command's spec, marked for the runner (`FlowJS`),
// which converts and writes the flow's values as acpx's runner does: under a key no flow's
// object has, and what the value was.
const JS_MARKER = "\u0000acpx";
const jsMarker = (kind, text) => (text === undefined ? { [JS_MARKER]: kind } : { [JS_MARKER]: kind, text });

// A member of a spec as JSON writes it, a BigInt and a number JSON has no literal for
// (`NaN`, the infinities) marked within it, and an object's keys that start with a NUL
// escaped with another, so none passes for a marker — or, for what `JSON.stringify` leaves
// out, or throws on (a cycle), a marker saying so.
function specJSON(value) {
  try {
    const json = JSON.stringify(value, (_key, member) => {
      if (typeof member === "bigint") return jsMarker("bigint", String(member));
      if (typeof member === "number" && !Number.isFinite(member)) return jsMarker("number", String(member));
      if (member !== null && typeof member === "object" && !Array.isArray(member)) {
        const keys = Object.keys(member);
        if (keys.some((key) => key.startsWith("\0"))) {
          return Object.fromEntries(keys.map((key) => [key.startsWith("\0") ? `\0${key}` : key, member[key]]));
        }
      }
      return member;
    });
    return json === undefined ? jsMarker("undefined") : JSON.parse(json);
  } catch (error) {
    return jsMarker("unserializable", error instanceof Error ? error.message : String(error));
  }
}

// A shell command's spec as the runner reads it, where acpx's runner holds the flow's own
// object: each member as JSON writes it, each argument by itself; `env` as Node's `spawn`
// converts it, `${value}`, leaving out `undefined`; and the arguments the command gets, as
// `spawn` makes them — `String(arg)` (a symbol, empty), or with `shell` as `Array.join`
// does. What converting throws, `spawn` would throw too.
// The spec's own members are what acpx spreads (`{ ...execution }`); `inherited` are the
// ones it reads off the spec itself, found on its prototype too: `cwd`, and for a shell
// action `timeoutMs`. A list's holes are read as `undefined`, as Node reads them.
function encodeExecution(execution, inherited) {
  if (execution === null || typeof execution !== "object") return execution;
  // Null-prototype, so a member named `__proto__` is a member.
  const encoded = Object.create(null);
  // What acpx's spread copies, each member read once; `args`, `env`, `shell` and `stdin`
  // are taken from these alone, never from the prototype.
  const own = Object.create(null);
  const members = Object.keys(execution);
  for (const key of members) own[key] = execution[key];
  for (const key of inherited) if (!Object.hasOwn(execution, key)) own[key] = execution[key];
  for (const [key, value] of Object.entries(own)) {
    if (value === undefined) continue;
    const name = key.startsWith("\0") ? `\0${key}` : key;
