  }
  return json === undefined ? { jsonUndefined: true } : { value: JSON.parse(json) };
}

// acpx's `setNodeValue`: the output a node's attempt produced — its callback's value, or
// one the runner made — is the node's output from now on.
function setOutput(params) {
  const node = flow.nodes[params.nodeId];
  let value = "value" in params ? params.value : returned.get(params.attemptId);
  // A shell action without `parse` outputs its command's result, whose `args` are its spec's.
  if ("value" in params && node && "exec" in node) value = commandResult(value, returned.get(params.attemptId));
  returned.delete(params.attemptId);
  committed.set(params.attemptId, value);
  Object.defineProperty(outputs, params.nodeId, { value, enumerable: true, configurable: true, writable: true });
}

// The run's live values as they are now, as acpx's `writeSnapshot` writes them with
// `JSON.stringify`: the input; `outputs` as the flow's code holds it — `ctx.outputs` is acpx's
// `state.outputs`, so a member a callback replaced, deleted or added is so there — each committed
// output by its attempt, which a node's result and its step hold whatever `outputs` now has; and
// what each attempt's callback returned last, not committed yet, which is its step's output only
// when that output is the callback's own value (#206).
function currentState() {
  const encode = (values) => Object.fromEntries([...values].map(([id, value]) => [id, returnedValue(value)]));
  return {
    input: returnedValue(input),
    outputs: returnedValue(outputs),
    attempts: encode(committed),
    returned: encode(returned),
  };
}

// The runner cancelled an attempt: its `signal` aborted with the reason — for one that
// failed, what its callback threw, when it failed with that.
function cancelAttempt(params) {
  const attempt = attemptFor(params.attemptId);
  let reason;
  if (params.reason === "timeout") reason = new TimeoutError(params.timeoutMs);
  else if (params.reason === "interrupted") reason = new InterruptedError();
  else reason = attempt.thrown ? attempt.thrown.error : new Error(params.message);
  attempt.controller.abort(reason);
}

// The runner is done with an attempt: nothing of it is kept.
function forgetAttempt(params) {
  returned.delete(params.attemptId);
  const attempt = attempts.get(params.attemptId);
  if (attempt) attempt.finished = true;
  attempts.delete(params.attemptId);
  running.delete(params.attemptId);
}

// A request's error as the code acpx runs would have thrown it: a `TypeError` for a value
// Node or JavaScript refuses — with Node's code, as Node's own — else an `Error` of the
// name given, with the properties Node gives a spawn failure.
function requestError({ message, data }) {
  const code = data?.props?.code;
  if (data?.name === "TypeError") {
    const error = Object.assign(new TypeError(message), data.props);
    if (code === undefined) return error;
    Object.defineProperty(error, "toString", {
      value() {
        return `${this.name} [${code}]: ${this.message}`;
      },
      writable: true,
      configurable: true,
    });
    return error;
  }
  const error = new Error(message);
  if (data?.name) error.name = data.name;
  if (data?.props) Object.assign(error, data.props);
  return error;
}

// What a callback threw, as acpx's runner records it: the message of an `Error`, else the
// thrown value as a string.
function errorReply(id, error) {
  const isError = error instanceof Error;
  send({
    id,
    error: {
      code: -32000,
      message: isError ? error.message : String(error),
      data: { isError, name: isError ? error.name : null, thrownType: error === null ? "null" : typeof error },
    },
  });
}

async function handle(message) {
  if (message.method === undefined) {
    const waiting = pending.get(message.id);
    pending.delete(message.id);
    if (!waiting) return;
    if (message.error) {
      waiting.reject(requestError(message.error));
    } else {
      waiting.resolve(message.result);
    }
    return;
  }
  try {
    let result = null;
    switch (message.method) {
      case "flow/load":
        result = await loadFlow(message.params);
        break;
      case "run/start":
        input = message.params.input;
        break;
      case "flow/title":
        result = await flowTitle(message.params);
        break;
      case "node/invoke":
        result = await invoke(message.params);
        break;
      case "outputs/set":
        setOutput(message.params);
        break;
      case "state/current":
        result = currentState();
        break;
      case "attempt/cancel":
        cancelAttempt(message.params);
        break;
      case "attempt/forget":
        forgetAttempt(message.params);
        break;
      case "host/tracked":
        // What the host still holds for attempts, for the runner's tests.
        result = { running: running.size, returned: returned.size };
        break;
      case "host/exit":
        if (message.id !== undefined) send({ id: message.id, result: null });
        channel.end(() => process.exit(0));
        return;
      case "host/release":
        release();
        return;
      default:
        throw Object.assign(new Error(`Method not found: ${message.method}`), { code: -32601 });
    }
    if (message.id !== undefined) send({ id: message.id, result });
  } catch (error) {
    if (message.id !== undefined) errorReply(message.id, error);
  }
}

let buffer = "";
channel.setEncoding("utf8");
channel.on("data", (chunk) => {
  buffer += chunk;
  for (let index; (index = buffer.indexOf("\n")) >= 0; ) {
    const line = buffer.slice(0, index);
    buffer = buffer.slice(index + 1);
    if (line.trim().length > 0) {
      trace?.("<-", line);
      // Not awaited: the host keeps reading while a callback waits on the runner.
      void handle(JSON.parse(line));
    }
  }
});
channel.on("end", () => process.exit(0));
channel.on("error", () => process.exit(1));

// A terminal's Ctrl-C reaches this process too. While the run goes on, the runner
// handles it, as acpx does, and tells the host when to go.
const INTERRUPTS = ["SIGINT", "SIGTERM", "SIGHUP"];
const ignore = () => {};
for (const signal of INTERRUPTS) {
  process.on(signal, ignore);
}

// A run that has ended — completed or waiting — leaves acpx's process to the flow's own
// timers and handles: acpx prints the result and ends once they have run out, with the
// code they leave (a later `process.exit(7)`: 7). So the host stops holding itself open
// for the runner, and takes Ctrl-C as acpx then does; it still goes if the runner does.
function release() {
  // The run is over: none of its attempts takes work any more.
  for (const attempt of attempts.values()) attempt.finished = true;
  attempts.clear();
  for (const signal of INTERRUPTS) {
    process.removeListener(signal, ignore);
  }
  channel.unref();
}

